const input = $input.first().json;
const fechaStr = input["Fecha preferida"];
let fecha;
if (fechaStr.includes('+') || fechaStr.includes('Z')) {
  fecha = new Date(fechaStr);
} else {
  const t = new Date(fechaStr);
  const m = t.getMonth();
  const dst = m >= 2 && m <= 9;
  fecha = new Date(fechaStr + (dst ? '+02:00' : '+01:00'));
}
const segundos = Math.floor(fecha.getTime() / 1000);
const fin = new Date(fecha.getTime() + 30*60*1000);
const fechaInicioMadrid = fecha.toLocaleString('es-ES', { timeZone:'Europe/Madrid', weekday:'long', year:'numeric', month:'long', day:'numeric', hour:'2-digit', minute:'2-digit' });
return [{ json: { ...input, segundos, fechaInicioISO: fecha.toISOString(), fechaFinISO: fin.toISOString(), fechaInicioMadrid } }];

