        : [{ label: 'Fecha cancelada', value: esc(fechaCancelada || '-'), big: true }],
      cierre: esCambio
        ? 'Si necesitas cambiar algo más, responde a este correo o escríbenos por WhatsApp.'
        : 'Si quieres volver a agendarla o buscar otra fecha, responde a este correo o escríbenos por WhatsApp y te ayudamos.',
      footer: 'Este correo se generó automáticamente<br/>tras ' + (esCambio ? 'modificar' : 'cancelar') + ' tu visita.',
    }),
  } });
}
return out;

