for (const it of $input.all()) {
  const e = (it && it.json) || {};
  if (!e.id) continue;
  const txt = String(e.description || '') + '\n' + String(e.summary || '');
  if (re.test(txt)) out.push({ json: e });
}
return out;

// 21-sep-2026 · Avisos por email de cancelacion/cambio + borrado de citas duplicadas en otras agendas.
// Cuelga DESPUES del Respond, asi que no anade latencia a la respuesta de voz ni del chatbot.
// Guarda el resultado original: en modo sub-workflow el chatbot recibe la salida del ULTIMO nodo
// ejecutado, y 'Aviso: devolver resultado' la re-emite tal cual al final de la cadena.
const r = $input.first().json;
const P = (x) => { try { return (x && typeof x.data === 'string') ? JSON.parse(x.data) : (x || {}); } catch (e) { return {}; } };
const esCambio = r.accion === 'cambio';

let leadId = null, fechaAnteriorSeg = null, fechaNuevaTxt = '';
if (esCambio) {
  try { leadId = $('Calc fechas cambio').first().json.Lead_id; } catch (e) {}
  try { fechaNuevaTxt = $('Calc fechas cambio').first().json.fechaInicioMadrid || ''; } catch (e) {}
  try {
    const g = P($('Get lead (cambio)').first().json);
    const lead = (g._embedded && g._embedded.leads && g._embedded.leads[0]) || g;
    const cf = (lead.custom_fields_values || []).find(c => c.field_id === 1330871);
    fechaAnteriorSeg = cf ? cf.values[0].value : null;
  } catch (e) {}
} else {
  try { leadId = $('Resolver Lead Id Cancelacion').first().json.Lead_id; } catch (e) {}
}

// Canal y motivo: el chatbot entra por 'Edit Fields', la voz por 'Edit Fields Retell'.
let fuente = '', motivo = '', nombreBot = '', telefonoBot = '';
for (const n of ['Edit Fields', 'Edit Fields Retell']) {
  try {
    const f = $(n).first().json;
    fuente = f.Fuente || ''; motivo = f['motivo de la consulta'] || '';
    nombreBot = f.nombre || ''; telefonoBot = f['numero de telefono'] || '';
    break;
  } catch (e) {}
}

return [{ json: {
  enviar: r.ok === true && !!leadId,
  accion: esCambio ? 'cambio' : 'cancelacion',
  leadId: leadId ? String(leadId) : null,
  fechaAnteriorSeg, fechaNuevaTxt, fuente, motivo, nombreBot, telefonoBot,
  resultado: r,
} }];

// Una busqueda por agenda activa (+ la general). Calendario_a_Kommo marca con
// extendedProperties.private.simarro_lead = <lead> la cita y sus duplicados en otras agendas, asi que
// aqui se busca por ese lead exacto: sin heuristicas de nombre ni telefono.
const P = (x) => { try { return (x && typeof x.data === 'string') ? JSON.parse(x.data) : (x || {}); } catch (e) { return {}; } };
const prep = $('Aviso: preparar').first().json;
const lead = P($('Aviso: leer lead').first().json);
const cf = (id) => { const c = (lead.custom_fields_values || []).find(x => x.field_id === id); return c ? c.values[0].value : null; };
// El evento vigente del lead no se toca: en un cambio es el NUEVO (Guardar Calendar Info ya lo apunto).
const eventoVigente = cf(1379552) || '';

const filas = $input.all().map(i => i.json).filter(a => a && a.calendar_id && a.active === true);
const vistos = new Set();
const out = [];
for (const a of [...filas, { calendar_id: 'consultingsimarroproperties@gmail.com', display_name: 'General' }]) {
  if (vistos.has(a.calendar_id)) continue;
  vistos.add(a.calendar_id);
  out.push({ json: { calendar_id: a.calendar_id, agenda: a.display_name || a.calendar_id, leadId: prep.leadId, eventoVigente } });
}
return out;

// La salida de 'Gemelos: buscar' va en el mismo orden que sus entradas (una por agenda).
const P = (x) => { try { return (x && typeof x.data === 'string') ? JSON.parse(x.data) : (x || {}); } catch (e) { return {}; } };
const cals = $('Gemelos: calendarios').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const cal = cals[i];
  if (!cal) return;
  const r = P(it.json);
  for (const ev of (r.items || [])) {
    if (!ev || !ev.id || ev.status === 'cancelled') continue;
    if (ev.id === cal.eventoVigente) continue;
    out.push({ json: { calendar_id: cal.calendar_id, agenda: cal.agenda, event_id: ev.id,
      titulo: ev.summary || '', inicio: (ev.start || {}).dateTime || (ev.start || {}).date || '' } });
  }
});
// Siempre un item: sin salida la cadena se cortaria antes de 'Aviso: devolver resultado'.
return out.length ? out : [{ json: { nada: true } }];

// Email interno a consultingsimarroproperties@gmail.com siempre; email al cliente solo si tiene uno
// valido en Kommo (primero el del contacto, si no el CF 'Email lead' 1372575). El email que manda el bot
// NO se usa: el 18-sep el chatbot paso simarroproperties@gmail.com como email de la clienta.
const P = (x) => { try { return (x && typeof x.data === 'string') ? JSON.parse(x.data) : (x || {}); } catch (e) { return {}; } };
const INTERNO = 'consultingsimarroproperties@gmail.com';
const prep = $('Aviso: preparar').first().json;
const lead = P($('Aviso: leer lead').first().json);
const contacto = P($input.first().json);
const esCambio = prep.accion === 'cambio';

const cfLead = (id) => { const c = (lead.custom_fields_values || []).find(x => x.field_id === id); return c ? c.values[0].value : null; };
const cfContacto = (code) => { const c = (contacto.custom_fields_values || []).find(x => x.field_code === code); return c ? c.values[0].value : null; };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (seg) => {
  if (!seg) return '';
  return new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', weekday: 'long', day: 'numeric',
    month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(Number(seg) * 1000));
};
const emailValido = (e) => {
  const v = String(e || '').trim();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) && !/simarro/i.test(v) ? v : '';
};

const nombre = contacto.name || [contacto.first_name, contacto.last_name].filter(Boolean).join(' ') || prep.nombreBot || 'Cliente';
const telefono = cfContacto('PHONE') || prep.telefonoBot || '';
const agente = cfLead(1373105) || '';
const tipo = (lead.pipeline_id === 13652227 || /valoraci/i.test(lead.name || '')) ? 'valoración' : 'visita';
const Tipo = tipo.charAt(0).toUpperCase() + tipo.slice(1);
const canal = /voz/i.test(prep.fuente) ? 'teléfono (agente de voz)' : 'WhatsApp (chatbot)';
// En una cancelacion el CF 'Dia de Visita' conserva la fecha cancelada; en un cambio ya es la nueva.
const fechaCancelada = esCambio ? '' : fmt(cfLead(1330871));
const fechaAnterior = esCambio ? fmt(prep.fechaAnteriorSeg) : '';
const fechaNueva = esCambio ? (prep.fechaNuevaTxt || fmt(cfLead(1330871))) : '';
const emailCliente = emailValido(cfContacto('EMAIL')) || emailValido(cfLead(1372575));

let duplicados = [];
try {
  duplicados = $('Gemelos: a borrar').all().map(i => i.json).filter(j => j && !j.nada).map(j => j.agenda);
} catch (e) {}

function buildEmail(p) {
  const accent = '#1F9D6E', accentLight = '#EBF5F0', accentBorder = '#C8E0D4';
  const headerTagBg = '#0A1512', heroBg = '#0F1715';
  const headerImg = 'https://raw.githubusercontent.com/AgentesIAMadrid/email-assets/main/Simarro_header.png';
  const logoImg = 'https://raw.githubusercontent.com/AgentesIAMadrid/email-assets/main/logo_simarro_properties.png';
  const dataRows = (p.dataBlocks || []).map((b, i) => `
    <table border="0" cellpadding="0" cellspacing="0" width="100%" ${i > 0 ? `style="border-top:1px solid ${accentBorder};"` : ''}>
      <tr><td style="padding:${i > 0 ? '14px' : '0'} 0 ${i === p.dataBlocks.length - 1 ? 0 : 14}px 0;">
        <p style="font-family:Arial,Helvetica,sans-serif;font-size:10px;color:#4A7A66;letter-spacing:3px;text-transform:uppercase;font-weight:bold;margin:0 0 4px 0;">${b.label}</p>
        <p style="font-family:Georgia,serif;font-size:${b.big ? 20 : 18}px;color:#0F1715;margin:0;line-height:1.25;word-break:break-word;">${b.value}</p>
      </td></tr>
    </table>`).join('');
  return `<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
<html xmlns="http://www.w3.org/1999/xhtml"><head>
<meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>${p.subject}</title>
<style>body{margin:0;padding:0;background-color:${heroBg};}table{border-collapse:collapse;}</style>
</head><body style="margin:0;padding:0;background-color:${heroBg};">
<center style="width:100%;background-color:${heroBg};padding:32px 0;">
<table align="center" border="0" cellpadding="0" cellspacing="0" style="width:100%;max-width:620px;background-color:#ffffff;border-radius:6px;overflow:hidden;box-shadow:0 20px 60px -20px rgba(0,0,0,0.55);">
<tr><td style="background-color:${headerTagBg};padding:14px 32px;">
  <p style="font-family:Arial,Helvetica,sans-serif;font-size:10px;letter-spacing:4px;color:${accent};text-transform:uppercase;font-weight:bold;margin:0;">${p.tag}</p>
</td></tr>
<tr><td align="center" valign="middle" bgcolor="${heroBg}" background="${headerImg}" height="260" style="height:260px;background-image:url('${headerImg}');background-position:center center;background-repeat:no-repeat;background-size:cover;">
  <table border="0" cellpadding="0" cellspacing="0" width="100%"><tr>
    <td align="center" valign="middle" style="padding:40px 0;background-color:rgba(10,21,18,0.52);">
      <img src="${logoImg}" alt="Simarro Properties" width="120" style="display:block;width:120px;height:auto;margin:0 auto;" />
    </td>
  </tr></table>
</td></tr>
<tr><td align="center" style="padding:32px 44px 0;background-color:#ffffff;">
  <p style="font-family:Arial,Helvetica,sans-serif;font-size:10px;color:#4A7A66;letter-spacing:5px;text-transform:uppercase;font-weight:bold;margin:0 0 10px 0;">${p.label}</p>
  <h1 style="font-family:Georgia,serif;font-size:38px;font-weight:normal;color:#0F1715;margin:0;line-height:1.05;">${p.h1}</h1>
</td></tr>
<tr><td align="center" style="padding:16px 56px 0;background-color:#ffffff;">
  <p style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#3F5651;margin:0;">${p.intro}</p>
</td></tr>
${dataRows ? `<tr><td style="padding:24px 44px 0;background-color:#ffffff;">
  <table border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color:${accentLight};border-radius:2px;border-left:3px solid ${accent};">
    <tr><td style="padding:24px 28px;">${dataRows}</td></tr>
  </table>
</td></tr>` : ''}
${p.cierre ? `<tr><td align="center" style="padding:24px 56px 0;background-color:#ffffff;">
  <p style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#3F5651;margin:0;">${p.cierre}</p>
</td></tr>` : ''}
<tr><td style="padding:0 0 32px;background-color:#ffffff;"></td></tr>
<tr><td align="center" style="background-color:${headerTagBg};padding:36px 44px;">
  <p style="font-family:Georgia,serif;font-size:28px;font-style:italic;color:#FFFFFF;margin:0;">Simarro <span style="color:${accent};">Properties</span></p>
  <p style="font-family:Arial,Helvetica,sans-serif;font-size:10px;color:${accent};letter-spacing:2px;text-transform:uppercase;margin:16px 0 0 0;">${p.footer}</p>
</td></tr>
</table></center></body></html>`;
}

const kommoUrl = 'https://simarro.kommo.com/leads/detail/' + prep.leadId;
const bloquesInternos = [
  { label: 'Cliente', value: esc(nombre), big: true },
  ...(esCambio
    ? [{ label: 'Nueva fecha & hora', value: esc(fechaNueva || '-'), big: true },
       { label: 'Fecha anterior', value: esc(fechaAnterior || '-') }]
    : [{ label: 'Fecha cancelada', value: esc(fechaCancelada || '-'), big: true }]),
  { label: 'Tipo', value: Tipo },
  { label: 'Teléfono', value: esc(telefono || '-') },
  { label: 'Agente', value: esc(agente || '-') },
  { label: 'Canal', value: esc(canal) },
  ...(prep.motivo ? [{ label: 'Motivo', value: esc(prep.motivo) }] : []),
  ...(duplicados.length ? [{ label: 'Duplicados borrados', value: esc(duplicados.join(', ')) }] : []),
  { label: 'Email al cliente', value: emailCliente ? 'Enviado a ' + esc(emailCliente) : 'No enviado: el cliente no tiene email en Kommo' },
  { label: 'Lead en Kommo', value: '<a href="' + kommoUrl + '" style="color:#0F4A38;">Abrir lead ' + esc(prep.leadId) + '</a>' },
];
const subjectInterno = esCambio
  ? `Visita cambiada — ${nombre} — ${fechaNueva}`
  : `Visita cancelada — ${nombre} — ${fechaCancelada}`;
const out = [{ json: {
  destino: 'interno', to: INTERNO, subject: subjectInterno,
  html: buildEmail({
    subject: esc(subjectInterno),
    tag: 'Notificación interna · ' + (esCambio ? 'cambio de cita' : 'cancelación'),
    label: esCambio ? 'Visita modificada' : 'Visita cancelada',
    h1: esCambio ? '<em style="font-style:italic;color:#0F4A38;">Cambio</em><br/>de cita.' : '<em style="font-style:italic;color:#0F4A38;">Cancelación</em><br/>de cita.',
    intro: esCambio
      ? `<strong style="color:#0F1715;">${esc(nombre)}</strong> ha cambiado su ${tipo} por ${esc(canal)}.`
      : `<strong style="color:#0F1715;">${esc(nombre)}</strong> ha cancelado su ${tipo} por ${esc(canal)}.`,
    dataBlocks: bloquesInternos,
    footer: 'Aviso interno · generado automáticamente',
  }),
} }];

if (emailCliente) {
  const subjectCliente = esCambio
    ? 'Tu visita con Simarro Properties tiene nueva fecha'
    : 'Tu visita con Simarro Properties ha sido cancelada';
  out.push({ json: {
    destino: 'cliente', to: emailCliente, subject: subjectCliente,
    html: buildEmail({
      subject: subjectCliente,
      tag: 'Inmobiliaria &amp; Inversión',
      label: esCambio ? 'Visita modificada' : 'Visita cancelada',
      h1: esCambio
        ? 'Tu visita tiene<br/><em style="font-style:italic;color:#0F4A38;">nueva fecha</em>.'
        : 'Tu visita ha sido<br/><em style="font-style:italic;color:#0F4A38;">cancelada</em>.',
      intro: esCambio
        ? `Hola, <strong style="color:#0F1715;">${esc(nombre)}</strong>. Hemos cambiado tu ${tipo} con Simarro Properties. Estos son los nuevos datos:`
        : `Hola, <strong style="color:#0F1715;">${esc(nombre)}</strong>. Te confirmamos que hemos cancelado tu ${tipo} con Simarro Properties.`,
      dataBlocks: esCambio
        ? [{ label: 'Nueva fecha & hora', value: esc(fechaNueva), big: true },
           ...(fechaAnterior ? [{ label: 'Fecha anterior', value: esc(fechaAnterior) }] : []),
           ...(agente ? [{ label: 'Tu agente', value: esc(agente) }] : [])]
        : [{ label: 'Fecha cancelada', value: esc(fechaCancelada || '-'), big: true }],
      cierre: esCambio
        ? 'Si necesitas cambiar algo más, responde a este correo o escríbenos por WhatsApp.'
        : 'Si quieres volver a agendarla o buscar otra fecha, responde a este correo o escríbenos por WhatsApp y te ayudamos.',
      footer: 'Este correo se generó automáticamente<br/>tras ' + (esCambio ? 'modificar' : 'cancelar') + ' tu visita.',
    }),
  } });
}
return out;

// El chatbot recibe la salida del ULTIMO nodo ejecutado: se re-emite el resultado original
// ({ok, accion, mensaje}) para que los emails y el borrado de duplicados no la alteren.
return [{ json: $('Aviso: preparar').first().json.resultado }];
